window.BIOMASTER = window.BIOMASTER || {};
window.BIOMASTER.THEORY_HTML = "<!-- CHUYÊN ĐỀ 1: TẾ BÀO & ENZYME -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellbio\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 1.1: Màng sinh chất, Cấu trúc Tế bào & Vận chuyển các chất</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Lý thuyết cốt lõi</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-2 text-slate-700\">\n                            <li><strong>Tính lỏng của màng:</strong> Acid béo không no (có nối đôi <i>cis</i>) làm tăng tính lỏng; acid béo no làm màng cứng hơn. <strong>Cholesterol</strong> ở tế bào động vật là \"đệm nhiệt độ\" (ngăn đóng băng khi trời lạnh, giảm tính lỏng khi trời nóng).</li>\n                            <li><strong>Vận chuyển qua màng:</strong> Lớp kép phospholipid cho các phân tử nhỏ không phân cực ($O_2, CO_2$) và hormone steroid đi qua trực tiếp. Các ion ($Na^+, K^+, Ca^{2+}$), Glucose và nước (qua kênh <i>Aquaporin</i>) phải đi qua kênh protein.</li>\n                            <li><strong>Bơm $Na^+/K^+$-ATPase:</strong> Tiêu tốn 1 ATP để bơm $3\\text{ }Na^+$ ra ngoài và $2\\text{ }K^+$ vào trong tế bào.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập Tự luận mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Khi chuyển một loài cá sống ở vùng biển ấm sang vùng biển băng giá Bắc Cực, tỉ lệ acid béo no/không no và hàm lượng cholesterol trong màng sinh chất của tế bào cá thay đổi như thế nào?</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Tế bào cá sẽ <strong>tăng tỉ lệ acid béo không no</strong> (tạo các điểm gấp khúc ngăn cản đuôi kị nước bó chặt) và <strong>tăng hàm lượng cholesterol</strong> để duy trì độ linh hoạt của màng ở nhiệt độ thấp.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellbio\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 1.2: Động học Enzyme (Michaelis - Menten) & Truyền tin Tế bào</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Động học Enzyme & Chất ức chế</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-2 text-slate-700\">\n                            <li><strong>Phương trình Michaelis - Menten:</strong> $v = \\frac{V_{\\max} \\cdot [S]}{K_m + [S]}$. Hằng số $K_m$ là nồng độ cơ chất tại đó $v = 0.5 V_{\\max}$. <strong>$K_m$ càng nhỏ thì ái lực của enzyme với cơ chất càng lớn.</strong></li>\n                            <li><strong>Chất ức chế cạnh tranh:</strong> Giống cơ chất, gắn vào trung tâm hoạt động $\\rightarrow$ <strong>$K_m$ tăng, $V_{\\max}$ không đổi</strong> (khắc phục được bằng cách tăng cao $[S]$).</li>\n                            <li><strong>Chất ức chế không cạnh tranh:</strong> Gắn vào vùng dị lập thể $\\rightarrow$ <strong>$V_{\\max}$ giảm, $K_m$ không đổi</strong>.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao (Giải độc Methanol bằng Ethanol)</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Giải thích tại sao bác sĩ truyền tĩnh mạch Ethanol ($C_2H_5OH$) để cứu sống bệnh nhân ngộ độc rượu công nghiệp Methanol ($CH_3OH$). Khi đó $K_m$ và $V_{\\max}$ của phản ứng phân giải Methanol bởi enzyme <i>ADH</i> thay đổi ra sao?</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Ethanol là <strong>chất ức chế cạnh tranh</strong> với Methanol tại trung tâm hoạt động của enzyme <i>ADH</i> ở gan, ngăn cản Methanol biến đổi thành Formaldehyde gây mù và tử vong. Khi có Ethanol, $K_m$ của phản ứng phân giải Methanol tăng lên còn $V_{\\max}$ không đổi.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellbio\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 1.3: Hô hấp Ti thể — Chất Ức chế Chuỗi Truyền $e^-$ (Rotenone, CN⁻) vs. Chất Phá ghép (DNP)</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Phân biệt 3 Nhóm Chất Tác động lên Màng trong Ti thể</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-2 text-slate-700\">\n                            <li><strong>1. Chất ức chế chuỗi truyền $e^-$:</strong> <i>Rotenone</i> (khóa phức hợp I, vẫn dùng được $FADH_2$), <i>Antimycin A</i> (khóa phức hợp III), <i>Cyanide ($CN^-$)/CO</i> (khóa phức hợp IV) $\\rightarrow$ Ngừng tiêu thụ $O_2$, ngừng tạo ATP.</li>\n                            <li><strong>2. Chất ức chế ATP synthase (Oligomycin):</strong> Khóa kênh $H^+$ của ATP synthase $\\rightarrow$ ngừng tổng hợp ATP, $H^+$ ứ đọng ở xoang gian màng làm chuỗi truyền $e^-$ và tiêu thụ $O_2$ chậm lại/dừng.</li>\n                            <li><strong>3. Chất phá ghép (2,4-DNP, FCCP, UCP1):</strong> Làm rò rỉ $H^+$ qua màng trong ti thể không qua ATP synthase $\\rightarrow$ <strong>ATP giảm về 0, nhưng tiêu thụ $O_2$ và sinh nhiệt tăng vọt</strong>.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Ti thể cô lập được cấp đủ Succinate, $O_2, ADP, P_i$. Thêm Oligomycin ở phút thứ 2 và thêm tiếp 2,4-DNP ở phút thứ 4. Mô tả sự thay đổi tốc độ tiêu thụ $O_2$ và tổng hợp ATP.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Khi thêm Oligomycin (phút 2): Tổng hợp ATP dừng ngay ($=0$), tiêu thụ $O_2$ giảm mạnh do ứ đọng $H^+$ ở xoang gian màng. Khi thêm tiếp DNP (phút 4): DNP giải phóng gradient $H^+$ qua màng nên tiêu thụ $O_2$ tăng vọt lên mức cực đại, nhưng tổng hợp ATP vẫn bằng 0 (năng lượng tỏa nhiệt).</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 2: DI TRUYỀN PHÂN TỬ, BIỂU SINH & CN GEN -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"molecular\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 2.1: Cấu trúc DNA, Nhân đôi, Phiên mã & Dịch mã</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Hệ thống Công thức Cốt lõi</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>$N = 2A + 2G$ ; $L = \\frac{N}{2} \\times 3.4 \\text{ \\AA}$ ; $M = N \\times 300 \\text{ đvC}$ ; $C = \\frac{N}{20}$</li>\n                            <li>$H = 2A + 3G$ ; Liên kết phosphodiester toàn gen: $HT = 2N - 2$</li>\n                            <li>Nhân đôi $k$ lần từ $a$ gen: $N_{mt} = a \\cdot N \\cdot (2^k - 1)$ ; Số gen có 2 mạch mới hoàn toàn $= a(2^k - 2)$</li>\n                            <li>Dịch mã 1 chuỗi polypeptide: Số aa môi trường cung cấp $= \\frac{rN}{3} - 1$ ; Số aa trong protein hoàn chỉnh $= \\frac{rN}{3} - 2$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Gen dài $4080 \\text{ \\AA}$ có $A = 20\\%N$. Gen nhân đôi 3 lần, các gen con đều phiên mã 2 lần, mỗi mRNA có 5 ribosome trượt qua 1 lần. Tính $H$, $A_{mt}, G_{mt}$ và tổng số amino acid môi trường cung cấp.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $N = 2400 \\Rightarrow A = T = 480; G = C = 720 \\Rightarrow H = 3120$. $A_{mt} = 3360, G_{mt} = 5040$. Số chuỗi polypeptide $= 2^3 \\times 2 \\times 5 = 80 \\Rightarrow \\text{Số aa}_{mt} = 80 \\times 399 = 31920$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"molecular\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 2.2: Đột biến Điểm (5-BU, $G^*$), Thí nghiệm $^{15}\\text{N}/^{14}\\text{N}$ & Cắt nối Exon - Intron</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Giải nhanh Đột biến & Đồng vị phóng xạ</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li><strong>5-BU:</strong> Gây thay thế $A-T \\rightarrow G-C$ sau tối thiểu <strong>3 lần nhân đôi</strong>. Số gen đột biến $G-C$ sau $k$ lần nhân đôi (nếu 5-BU chỉ tác động ở lần 1) $= 2^{k-2} - 1$.</li>\n                            <li><strong>Guanine dạng hiếm ($G^*$):</strong> Gây thay thế $G^*-C \\rightarrow A-T$ sau tối thiểu <strong>2 lần nhân đôi</strong>. Số gen đột biến $= 2^{k-1} - 1$.</li>\n                            <li><strong>Thí nghiệm Meselson - Stahl ($a$ phân tử DNA $^{15}\\text{N}$ chuyển sang $^{14}\\text{N}$ nhân đôi $k$ lần):</strong> Số DNA lai ($^{15}\\text{N}-^{14}\\text{N}$) $= 2a$ ; Số DNA chỉ chứa $^{14}\\text{N} = a(2^k - 2)$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Nuôi 5 vi khuẩn <i>E. coli</i> chứa DNA $^{15}\\text{N}$ trong môi trường $^{14}\\text{N}$ qua 4 thế hệ, rồi chuyển toàn bộ sang môi trường $^{15}\\text{N}$ nhân đôi thêm 2 lần. Có bao nhiêu phân tử DNA hoàn toàn không chứa mạch $^{14}\\text{N}$?</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Sau 4 thế hệ ở $^{14}\\text{N}$: Tạo $5 \\times 2^4 = 80$ DNA (có $160 - 10 = 150$ mạch $^{14}\\text{N}$). Sau 2 thế hệ tiếp theo ở $^{15}\\text{N}$: Tổng DNA $= 80 \\times 4 = 320$. Số DNA không chứa mạch $^{14}\\text{N} = 320 - 150 = 170$ phân tử.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"molecular\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 2.3: Operon Lac/Trp, Di truyền Biểu sinh (Epigenetics) & Công nghệ CRISPR-Cas9 / PCR</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Lý thuyết Chuyên sâu HSG Tỉnh</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li><strong>Epigenetics:</strong> Acetyl hóa Histone làm giãn xoắn NST $\\rightarrow$ tăng phiên mã; Methyl hóa Cytosine (DNA) làm đóng xoắn dị nhiễm sắc $\\rightarrow$ bất hoạt gen.</li>\n                            <li><strong>In dấu hệ gen (Imprinting):</strong> Gen <i>Igf2</i> ở chuột chỉ biểu hiện từ alen của bố, alen từ mẹ bị methyl hóa bất hoạt hoàn toàn.</li>\n                            <li><strong>Kỹ thuật PCR ($n$ chu kỳ từ 1 DNA):</strong> Tổng DNA $= 2^n$ ; Số phân tử DNA có 2 mạch chuẩn đúng bằng đoạn mục tiêu $= 2^n - 2n$ ; Tổng số mồi tiêu thụ $= 2(2^n - 1)$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh (In dấu hệ gen <i>Igf2</i>)</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Ở chuột, alen $Igf2^+$ quy định kích thước bình thường, $Igf2^-$ gây kiểu hình chuột lùn. Do in dấu hệ gen, chỉ alen nhận từ bố mới biểu hiện. Xác định tỉ lệ kiểu hình đời con của phép lai: ♂ $Igf2^+ Igf2^- \\times$ ♀ $Igf2^+ Igf2^+$.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Kiểu hình chuột con phụ thuộc duy nhất vào giao tử của bố. Bố $Igf2^+ Igf2^-$ tạo $\\frac{1}{2} Igf2^+ : \\frac{1}{2} Igf2^-$ nên đời con có tỉ lệ: <strong>1 bình thường : 1 lùn</strong>.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 3: PHÂN BÀO & ĐỘT BIẾN NST -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellular\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 3.1: Nguyên phân, Giảm phân & Thụ tinh</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Nguyên phân & Giảm phân</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>$a$ tế bào $2n$ nguyên phân $k$ lần: Số tế bào con $= a \\cdot 2^k$ ; $\\text{NST}_{mt} = a \\cdot 2n \\cdot (2^k - 1)$.</li>\n                            <li>Số NST đơn và tâm động ở Kỳ giữa NP $= 2n$ (kép), ở Kỳ sau NP $= 4n$ (đơn).</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> 10 tế bào mầm đực ruồi giấm ($2n=8$) nguyên phân 4 lần rồi tất cả giảm phân tạo tinh trùng (hiệu suất thụ tinh $10\\%$). Tính tổng NST môi trường cung cấp và số hợp tử.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Tổng NST cung cấp $= 10 \\times 8 \\times (2^4 - 1) + 160 \\times 8 = 2480$ NST. Số hợp tử $= 160 \\times 4 \\times 10\\% = 64$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellular\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 3.2: Giao tử Trao đổi chéo & Quy tắc Giao tử Tứ bội ($4n$)</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Giao tử TĐC & Đa bội $4n$</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>TĐC tại 1 điểm ở $m$ cặp: $2^{n+m}$ ; TĐC tại 2 điểm không cùng lúc ở $m$ cặp: $2^n \\cdot 3^m$ ; TĐC tại 2 điểm cùng lúc và không cùng lúc: $2^{n+2m}$.</li>\n                            <li>Từ $k$ tế bào sinh tinh: Số loại tinh trùng tối đa $= \\min(2k, \\text{Tổng LT})$ (không TĐC) hoặc $\\min(4k, \\text{Tổng LT})$ (có TĐC).</li>\n                            <li>Giao tử $4n$: $AAaa \\rightarrow \\frac{1}{6}AA : \\frac{4}{6}Aa : \\frac{1}{6}aa$ ; $AAAa \\rightarrow \\frac{1}{2}AA : \\frac{1}{2}Aa$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Cho phép lai $P: AAaaBBbb \\times AAaaBBbb$. Tính tỉ lệ kiểu hình mang 2 tính trạng trội và tỉ lệ kiểu gen đồng hợp cả 2 cặp ở $F_1$.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Tỉ lệ KH 2 trội $= \\frac{35}{36} \\times \\frac{35}{36} = \\frac{1225}{1296}$. Tỉ lệ KG đồng hợp 2 cặp $= \\frac{2}{36} \\times \\frac{2}{36} = \\frac{1}{324}$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"cellular\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 3.3: Điểm kiểm soát Chu kỳ Tế bào ($p53, Rb$), Rối loạn GP I / GP II & Đột biến Cấu trúc NST</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Lý thuyết Biện luận HSG Tỉnh</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li><strong>Gen ức chế khối u ($p53, Rb$):</strong> Đột biến mang tính <strong>lặn</strong> ở cấp tế bào (phải hỏng cả 2 alen mới gây ung thư). <strong>Gen tiền ung thư (Proto-oncogene: <i>Ras, Myc</i>):</strong> Đột biến hoạt hóa mang tính <strong>trội</strong> (chỉ cần 1 alen đột biến thành Oncogene).</li>\n                            <li><strong>Rối loạn GP I vs. GP II ở cơ thể dị hợp $Aa$ (không TĐC):</strong> Rối loạn GP I tạo giao tử $Aa$; Rối loạn GP II tạo giao tử $AA$ hoặc $aa$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Bố mẹ nhìn màu bình thường ($X^M Y \\times X^M X^m$) sinh con mắc hội chứng Klinefelter và bị mù màu ($X^m X^m Y$). Không có TĐC. Rối loạn phân bào đã xảy ra ở đâu?</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Rối loạn xảy ra ở <strong>người mẹ tại lần Giảm phân II</strong> (hai nhiễm sắc tử chị em $X^m$ không phân ly tạo trứng $X^m X^m$ kết hợp với tinh trùng $Y$ của bố).</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 4: QUY LUẬT DI TRUYỀN & BẢN ĐỒ GEN -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"mendel\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 4.1: Quy luật Phân ly Độc lập (Mendel) & Tương tác Gen</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Tổ hợp Nhanh</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Tỉ lệ kiểu hình mang $k$ tính trạng trội trong phép lai $n$ cặp dị hợp tự thụ: $C^k_n \\left(\\frac{3}{4}\\right)^k \\left(\\frac{1}{4}\\right)^{n-k}$.</li>\n                            <li>Tỉ lệ kiểu gen dị hợp $k$ cặp gen trong phép lai $n$ cặp dị hợp tự thụ: $C^k_n \\left(\\frac{1}{2}\\right)^n$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Cho $P: AaBbDdEe \\times AaBbDdEe$. Tính xác suất thu được cá thể ở $F_1$ mang 3 tính trạng trội và đồng hợp về 2 cặp gen.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Có 1 cặp đồng hợp lặn ($1/4$), 1 cặp đồng hợp trội ($1/4$) và 2 cặp dị hợp ($(2/4)^2$). Xác suất $= C^1_4 \\times C^1_3 \\times \\frac{1}{4} \\times \\frac{1}{4} \\times \\left(\\frac{2}{4}\\right)^2 = \\frac{3}{16}$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"mendel\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 4.2: Công thức Giải nhanh Hoán vị Gen & Liên kết Giới tính</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Hệ thức Morgan</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>$\\%A-B- = 50\\% + \\%aabb$ ; $\\%A-bb = \\%aaB- = 25\\% - \\%aabb$.</li>\n                            <li>Tổng tỉ lệ đồng hợp 2 cặp ($\\frac{AB}{AB} + \\frac{Ab}{Ab} + \\frac{aB}{aB} + \\frac{ab}{ab}$) luôn bằng tổng tỉ lệ dị hợp 2 cặp ($\\frac{AB}{ab} + \\frac{Ab}{aB}$).</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Cho $\\frac{AB}{ab} \\times \\frac{AB}{ab}$ (hoán vị 2 giới với $f = 20\\%$). Tính tỉ lệ cá thể ở $F_1$ mang 2 tính trạng trội nhưng chỉ dị hợp 1 cặp gen.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $\\underline{AB} = \\underline{ab} = 0.4 ; \\underline{Ab} = \\underline{aB} = 0.1$. Tỉ lệ $\\frac{AB}{Ab} + \\frac{AB}{aB} = 2(0.4 \\times 0.1) + 2(0.4 \\times 0.1) = 16\\%$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"mendel\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 4.3: Lập Bản đồ Gen 3 Điểm, Nhiễu NST ($I$), Thử nghiệm Cis-Trans & Bản đồ Tâm động</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Công thức Bản đồ 3 Điểm & Nấm <i>Neurospora</i></h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Hệ số trùng hợp $C = \\frac{f_{\\text{kép thực tế}}}{f_1 \\times f_2}$ ; Độ nhiễu $I = 1 - C$.</li>\n                            <li>Khoảng cách từ gen đến Tâm động ở nấm <i>Neurospora</i>: $d = \\frac{1}{2} \\times \\frac{\\text{Số nang SDS}}{\\text{Tổng số nang}} \\times 100\\text{ (cM)}$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Ba gen theo thứ tự $A - B - D$ có $d(A-B) = 20\\text{ cM}$, $d(B-D) = 10\\text{ cM}$, độ nhiễu $I = 0.25$. Tính tỉ lệ giao tử TĐC kép của cơ thể $\\frac{ABD}{abd}$.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $C = 1 - 0.25 = 0.75 \\Rightarrow f_{\\text{kép}} = 0.75 \\times 0.2 \\times 0.1 = 0.015 = 1.5\\% \\Rightarrow \\underline{AbD} = \\underline{aBd} = 0.75\\%$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 5: DI TRUYỀN QUẦN THỂ, PHẢ HỆ & TIẾN HÓA -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"population\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 5.1: Quần thể Tự phối & Ngẫu phối (Hardy - Weinberg)</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Cốt lõi</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Tự phối $n$ thế hệ: $Aa_n = h \\cdot (1/2)^n$ ; $AA_n = d + \\frac{h - Aa_n}{2}$.</li>\n                            <li>Ngẫu phối cân bằng: $p^2 AA + 2pq Aa + q^2 aa = 1$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Quần thể $P: 0.2AA : 0.6Aa : 0.2aa$. Tính tỉ lệ dị hợp ở $F_3$ khi tự thụ phấn và khi ngẫu phối.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Tự thụ phấn: $Aa = 0.6 \\times (1/8) = 0.075$. Ngẫu phối: $Aa = 2pq = 2 \\times 0.5 \\times 0.5 = 0.50$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"population\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 5.2: Phả hệ Người, Quần thể Đa Alen (ABO) & Giao phối Chọn lọc</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Tách giao tử & Nhóm máu ABO</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Người kiểu hình trội từ quần thể cân bằng có tần số $q(a)$: Cho giao tử $a = \\frac{q}{1+q}$ và $A = \\frac{1}{1+q}$.</li>\n                            <li>Nhóm máu ABO: $r(I^O) = \\sqrt{\\%\\text{O}}$ ; $p(I^A) = \\sqrt{\\%\\text{A} + \\%\\text{O}} - r$ ; $q(I^B) = \\sqrt{\\%\\text{B} + \\%\\text{O}} - r$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Quần thể cân bằng có $4\\%$ máu O và $21\\%$ máu B. Hai người máu A trong quần thể kết hôn, xác suất sinh con đầu lòng máu A là bao nhiêu?</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $r = 0.2, q = 0.3, p = 0.5$. Người máu A có dạng $(\\frac{5}{9}I^A I^A : \\frac{4}{9}I^A I^O) \\rightarrow$ giao tử $I^O = \\frac{2}{9}$. XS con máu A $= 1 - (\\frac{2}{9})^2 = \\frac{77}{81}$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"population\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 5.3: Động học Tiến hóa (Chọn lọc $s$, Nội phối $F$, Kích thước $N_e$) & Cây Chủng loại</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Mô hình Toán Tiến hóa</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Đào thải hoàn toàn lặn ($s=1$): $q_n = \\frac{q_0}{1 + n q_0}$. Ưu thế dị hợp: $\\hat{q} = \\frac{s_1}{s_1 + s_2}$.</li>\n                            <li>Hệ số nội phối: $F = 1 - \\frac{H_{\\text{obs}}}{2pq}$. Kích thước hiệu quả: $N_e = \\frac{4 N_m N_f}{N_m + N_f}$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Quần thể có cấu trúc $0.52 AA : 0.16 Aa : 0.32 aa$. Tính hệ số nội phối $F$.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $p = 0.6, q = 0.4 \\Rightarrow 2pq = 0.48 \\Rightarrow F = 1 - \\frac{0.16}{0.48} = \\frac{2}{3} \\approx 0.667$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 6: SINH LÝ THỰC VẬT - ĐỘNG VẬT & SINH THÁI -->\n            <div class=\"content-card overflow-hidden\" data-topic=\"physiology\" data-level=\"basic\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 6.1: Sinh lý Thực vật - Động vật Cơ bản & Chuỗi Thức ăn</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-basic\">🟢 Cơ bản</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Công thức Lưu lượng tim & Sinh thái cơ bản</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Lưu lượng tim: $CO = HR \\times SV = HR \\times (EDV - ESV)$.</li>\n                            <li>Hiệu suất sinh thái: $H\\% = \\frac{E_n}{E_{n-1}} \\times 100\\%$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-emerald-50/50 p-4 rounded-xl border border-emerald-100\">\n                        <h3 class=\"font-semibold text-emerald-800 mb-2\">✍️ Bài tập mẫu</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Nhịp tim $75\\text{ lần/phút}$, $EDV = 120\\text{ ml}$, $ESV = 50\\text{ ml}$. Tính lưu lượng tim $CO$.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-emerald-600 text-white px-3 py-1.5 rounded hover:bg-emerald-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-emerald-200 text-sm text-slate-700 space-y-1\">\n                            <p>• $SV = 120 - 50 = 70\\text{ ml} \\Rightarrow CO = 75 \\times 70 = 5250\\text{ ml/phút} = 5.25\\text{ lít/phút}$.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"physiology\" data-level=\"adv\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 6.2: Quang hợp $C_3/C_4/CAM$, Đường cong Sống sót & Khuếch đại Sinh học</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-adv\">🟡 Nâng cao</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-emerald-700 mb-2\">📖 Chi phí ATP Quang hợp & Sinh thái nâng cao</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li>Tổng hợp 1 Glucose: Cây $C_3$ cần $18\\text{ ATP} + 12\\text{ NADPH}$; Cây $C_4/CAM$ cần $30\\text{ ATP} + 12\\text{ NADPH}$.</li>\n                            <li>Đường cong sống sót: Kiểu I (người, thú lớn), Kiểu II (chim, thủy tức), Kiểu III (cá, hàu, thực vật).</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-amber-50/50 p-4 rounded-xl border border-amber-100\">\n                        <h3 class=\"font-semibold text-amber-900 mb-2\">✍️ Bài tập Vận dụng cao</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Giải thích tại sao trong hồ nhiễm DDT, chim ăn cá ở đỉnh chuỗi thức ăn lại chịu độc tính nặng nhất.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-amber-600 text-white px-3 py-1.5 rounded hover:bg-amber-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-amber-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Do hiện tượng <strong>khuếch đại sinh học (Biomagnification)</strong>: DDT tan trong mỡ và không bị phân giải nên tích lũy tăng gấp bội qua mỗi bậc dinh dưỡng.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"content-card overflow-hidden\" data-topic=\"physiology\" data-level=\"hsg\">\n                <div class=\"bg-slate-50 px-5 py-3.5 border-b border-slate-200 flex justify-between items-center\">\n                    <h2 class=\"font-bold text-base md:text-lg text-emerald-800\">Chuyên đề 6.3: Thế Nước $\\Psi_w$, Độc tố Thần kinh (TTX, TEA), Trục Nội tiết (Basedow), Thận ($GFR$) & Đa dạng Sinh thái ($H^\\prime$)</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-semibold level-badge-hsg\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div>\n                        <h3 class=\"font-semibold text-rose-700 mb-2\">📖 Công thức & Cơ chế Tự luận HSG Tỉnh</h3>\n                        <ul class=\"list-disc list-inside text-sm space-y-1.5 text-slate-700\">\n                            <li><strong>Thế nước:</strong> $\\Psi_w = \\Psi_s + \\Psi_p$ ($\\Psi_s = -iCRT$).</li>\n                            <li><strong>Độ thanh thải thận:</strong> $C_x = \\frac{U_x \\times V}{P_x}$ ($C_{\\text{Inulin}} = GFR$).</li>\n                            <li><strong>Chỉ số đa dạng Simpson ($D$) & Shannon ($H^\\prime$):</strong> $D = 1 - \\sum p_i^2$ ; $H^\\prime = -\\sum p_i \\ln(p_i)$.</li>\n                        </ul>\n                    </div>\n                    <div class=\"bg-rose-50/50 p-4 rounded-xl border border-rose-100\">\n                        <h3 class=\"font-semibold text-rose-900 mb-2\">✍️ Bài tập HSG Tỉnh</h3>\n                        <p class=\"text-sm text-slate-700 mb-3\"><strong>Đề bài:</strong> Phân biệt nồng độ $TRH, TSH, T_3/T_4$ giữa người bị bướu cổ do thiếu Iodine và người mắc bệnh Basedow.</p>\n                        <button onclick=\"toggleSolution(this)\" class=\"text-xs bg-rose-600 text-white px-3 py-1.5 rounded hover:bg-rose-700 transition\">Xem lời giải chi tiết</button>\n                        <div class=\"solution hidden mt-3 pt-3 border-t border-rose-200 text-sm text-slate-700 space-y-1\">\n                            <p>• Thiếu Iodine: $T_3/T_4$ giảm thấp $\\rightarrow$ mất ức chế ngược làm $TRH, TSH$ tăng cao. Bệnh Basedow: Kháng thể TSI kích thích tuyến giáp tiết quá nhiều $T_3/T_4$ (tăng cao) $\\rightarrow$ ức chế ngược làm $TRH, TSH$ giảm thấp.</p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 7: CẨM NANG NHẬN DIỆN NHANH -->\n            <div class=\"content-card border-2 border-amber-300 overflow-hidden\" data-topic=\"recognition\" data-level=\"adv\">\n                <div class=\"bg-amber-50 px-5 py-3.5 border-b border-amber-200 flex justify-between items-center\">\n                    <h2 class=\"font-extrabold text-base md:text-lg text-amber-900\">⚡ Chuyên đề 7: BẢNG MA TRẬN NHẬN DIỆN NHANH QUY LUẬT DI TRUYỀN</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-bold level-badge-adv\">🟡 Kỹ năng VDC & HSG</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6\">\n                    <div class=\"formula-box p-4 rounded-xl text-xs space-y-1.5\">\n                        <p><strong>• Tương tác Bổ sung:</strong> $F_2$ có $9:7$ ($F_a \\rightarrow 1:3$) ; $9:6:1$ ($F_a \\rightarrow 1:2:1$) ; $9:3:3:1$ ($F_a \\rightarrow 1:1:1:1$).</p>\n                        <p><strong>• Tương tác Át chế:</strong> $12:3:1$ ($F_a \\rightarrow 2:1:1$) ; $13:3$ ($F_a \\rightarrow 3:1$) ; $9:3:4$ ($F_a \\rightarrow 1:1:2$).</p>\n                        <p><strong>• Tương tác Cộng gộp:</strong> $15:1$ ($F_a \\rightarrow 3:1$) hoặc biến thiên theo $C^k_{2n}$ ($1:4:6:4:1$).</p>\n                        <p><strong>• Gen gây chết đồng hợp trội ($AA$ chết):</strong> Tỉ lệ $2:1$ (hoặc $6:3:2:1$).</p>\n                    </div>\n                    <div class=\"trap-box p-4 rounded-xl text-xs space-y-1.5\">\n                        <p><strong>• Di truyền ngoài nhân:</strong> Lai thuận nghịch con luôn giống mẹ 100%.</p>\n                        <p><strong>• Hiệu ứng dòng mẹ (Ốc <i>Limnaea</i>):</strong> Kiểu hình con do kiểu gen mẹ quyết định; tỉ lệ $3:1$ xuất hiện ở $F_3$.</p>\n                        <p><strong>• Phụ thuộc giới tính (Hói đầu):</strong> Gen trên NST thường, $Bb$ trội ở nam nhưng lặn ở nữ.</p>\n                    </div>\n                </div>\n            </div>\n\n            <!-- CHUYÊN ĐỀ 8: TUYỂN TẬP 8 ĐỀ THI TỰ LUẬN CÁC TỈNH -->\n            <div class=\"content-card border-2 border-rose-300 overflow-hidden\" data-topic=\"provinces\" data-level=\"hsg\">\n                <div class=\"bg-gradient-to-r from-rose-700 to-red-800 px-5 py-4 text-white flex justify-between items-center\">\n                    <h2 class=\"font-extrabold text-base md:text-lg\">🏆 Chuyên đề 8: TUYỂN TẬP CÂU HỎI TỰ LUẬN ĐỀ THI HSG CÁC TỈNH (8 TỈNH THÀNH)</h2>\n                    <span class=\"px-2.5 py-1 rounded-full text-xs font-bold bg-white text-rose-800\">🔴 HSG Tỉnh</span>\n                </div>\n                <div class=\"p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-4 text-xs\">\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Bắc Ninh (Operon Lac $F^\\prime$):</span> Chủng $I^- P^+ O^+ Z^+ Y^- / F^\\prime I^+ P^- O^+ Z^- Y^+$ trong môi trường có lactose chỉ tổng hợp $\\beta$-galactosidase, không tổng hợp permease (do $P^-$ trên $F^\\prime$ bị hỏng).\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Nghệ An (HVG + Liên kết giới tính):</span> ♀ $\\frac{AB}{ab} X^D X^d \\times$ ♂ $\\frac{AB}{ab} X^D Y$ cho $aabbD- = 10.5\\% \\Rightarrow aabb = 14\\% \\Rightarrow \\underline{ab}_{♀} = 0.28 \\Rightarrow f = 44\\%$.\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Thanh Hóa (Phả hệ 2 bệnh):</span> Chồng $(\\frac{1}{3}AA : \\frac{2}{3}Aa) X^B Y \\times$ Vợ $(\\frac{1}{2}AA : \\frac{1}{2}Aa) X^B X^b \\rightarrow$ XS sinh con trai không mắc cả 2 bệnh $= \\frac{11}{12} \\times \\frac{1}{4} = \\frac{11}{48}$.\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Hà Nội (Hở van 2 lá):</span> Máu trào ngược về nhĩ trái làm $SV$ giảm, nhịp tim $HR$ tăng, áp lực nhĩ trái tăng gây ứ máu mao mạch phổi $\\rightarrow$ phù phổi và khó thở.\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Nam Định (Cây $C_3$ và $C_4$ trong chuông kín):</span> Cây lúa ($C_3$) chết trước vì điểm bù $CO_2$ cao ($30-70\\text{ ppm}$), bị ngô ($C_4$, enzyme PEP carboxylase) lấy cạn $CO_2$.\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Hải Phòng (Bắt - Đánh dấu - Thả - Bắt lại):</span> $N = \\frac{120 \\times 150}{24} = 750$. Nếu sơn làm ốc dễ bị ăn thịt thì $R$ giảm $\\rightarrow N$ tính được cao hơn thực tế.\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề Đà Nẵng (Độc tố Thần kinh):</span> TTX khóa kênh $Na^+$ (mất ĐTHĐ, liệt mềm); Curare khóa thụ thể ACh (liệt mềm); Organophosphate ức chế AChE (co giật cơ liên tục).\n                    </div>\n                    <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200\">\n                        <span class=\"font-bold text-indigo-800\">📍 Đề TP.HCM (Lysosome & Bơm $H^+$):</span> Lysosome duy trì $pH \\approx 4.5-5.0$ nhờ bơm $H^+$-ATPase. Vỡ 1 vài Lysosome không gây hại vì enzyme bất hoạt ở $pH = 7.2$ của bào tương.\n                    </div>\n                </div>\n            </div>";
